public class Main {
    interface Animal { default String sound() { return "?"; } }
    static class Dog implements Animal { public String sound() { return "woof"; } }
    static class Puppy extends Dog { public String sound() { return "yip"; } }

    static String pick(Object o) { return "static dispatch -> Object overload"; }
    static String pick(String s) { return "static dispatch -> String overload"; }

    public static void main(String[] args) throws Exception {
        System.out.println("=== dynamic dispatch (invokevirtual / invokeinterface) ===");
        Animal a1 = new Dog(), a2 = new Puppy();
        System.out.println("    Dog   via Animal ref : " + a1.sound());
        System.out.println("    Puppy via Animal ref : " + a2.sound());
        System.out.println("    same static type, different runtime method");

        System.out.println("=== static dispatch (overload resolved at compile time) ===");
        Object o = "hello";
        System.out.println("    pick(o)            : " + pick(o));
        System.out.println("    pick((String) o)   : " + pick((String) o));
        System.out.println("    runtime type is String but overload picked by STATIC type");

        System.out.println("=== reflection reveals the runtime class ===");
        System.out.println("    a2.getClass()                     : " + a2.getClass().getName());
        System.out.println("    declaring class of sound()        : "
                + a2.getClass().getMethod("sound").getDeclaringClass().getName());
        System.out.println("    Puppy is-a Dog                    : " + (a2 instanceof Dog));
        System.out.println("    Dog   is-a Animal                 : " + (a1 instanceof Animal));
    }
}
